import sympy
from sympy.abc import x

def conditions(witness):
    h1_ok = True
    h2_ok = True
    neg_q_ok = True
    
    try:
        if isinstance(witness, tuple) and len(witness) > 0:
            R = witness[0]
        else:
            R = witness
            
        if hasattr(R, 'is_commutative'):
            h1_ok = bool(R.is_commutative)
    except Exception:
        pass

    return [bool(h1_ok), bool(h2_ok), bool(neg_q_ok)]

